    public void store(String identifier, String sensitiveData) throws Exception {
        byte[] plaintext = sensitiveData.getBytes(StandardCharsets.UTF_8);
        byte[] iv = new byte[IV_LENGTH_BYTE];
        secureRandom.nextBytes(iv);

        Cipher cipher = Cipher.getInstance(ALGORITHM);
        GCMParameterSpec spec = new GCMParameterSpec(TAG_LENGTH_BIT, iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, spec);

        byte[] ciphertext = cipher.doFinal(plaintext);
        Arrays.fill(plaintext, (byte) 0);

        byte[] record = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, record, 0, iv.length);
        System.arraycopy(ciphertext, 0, record, iv.length, ciphertext.length);

        Map<String, String> records = loadAllRecords();
        records.put(identifier, Base64.getEncoder().encodeToString(record));
        saveAllRecords(records);
    }

    public String retrieve(String identifier) throws Exception {
        Map<String, String> records = loadAllRecords();
        String encoded = records.get(identifier);
        if (encoded == null) {
            return null;
        }

        byte[] record = Base64.getDecoder().decode(encoded);
        byte[] iv = new byte[IV_LENGTH_BYTE];
        System.arraycopy(record, 0, iv, 0, IV_LENGTH_BYTE);

        byte[] ciphertext = new byte[record.length - IV_LENGTH_BYTE];
        System.arraycopy(record, IV_LENGTH_BYTE, ciphertext, 0, ciphertext.length);

        Cipher cipher = Cipher.getInstance(ALGORITHM);
        GCMParameterSpec spec = new GCMParameterSpec(TAG_LENGTH_BIT, iv);
        cipher.init(Cipher.DECRYPT_MODE, secretKey, spec);

        byte[] plaintext = cipher.doFinal(ciphertext);
        String result = new String(plaintext, StandardCharsets.UTF_8);
        Arrays.fill(plaintext, (byte) 0);

        return result;
    }

    private Map<String, String> loadAllRecords() throws IOException {
        Map<String, String> records = new HashMap<>();
        if (Files.exists(storagePath)) {
            try (BufferedReader reader = Files.newBufferedReader(storagePath)) {
                String line;
                while ((line = reader.readLine()) != null) {
                    String[] parts = line.split(":", 2);
                    if (parts.length == 2) {
                        records.put(parts[0], parts[1]);
                    }
                }
            }
        }
        return records;
    }

    private void saveAllRecords(Map<String, String> records) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(storagePath)) {
            for (Map.Entry<String, String> entry : records.entrySet()) {
                writer.write(entry.getKey() + ":" + entry.getValue());
                writer.newLine();
            }
        }
    }

